@pytest.mark.parametrize("scenario_case", _PARAM_CASES, ids=_PARAM_IDS)
def test_upload_image(api_client, config_test_data, scenario_case):
    """
    Test the /pet/{petId}/uploadImage endpoint.
    """
    petId = scenario_case.get("petId", config_test_data['petId'])
    additionalMetadata = scenario_case.get("additionalMetadata", None)
    statusCode = scenario_case["statusCode"]
    scenario = scenario_case["scenario"]

    endpoint = f"/pet/{petId}/uploadImage"
    params = {"additionalMetadata": additionalMetadata} if additionalMetadata else {}

    # Validate request schema
    request_schema = {
        "type": "object",
        "properties": {
            "petId": {"type": "integer"},
            "additionalMetadata": {"type": "string"}
        },
        "required": ["petId"]
    }
    validator.validate_json({"petId": petId, **params}, request_schema)

    # Make the API request
    response = api_client.post(endpoint, data=params)

    # Validate response status code
    assert response.status_code == statusCode, f"Expected {statusCode}, got {response.status_code}"

    # Validate response schema
    validation_result = validator.validate_schema_by_response(endpoint, 'post', str(statusCode), response)
    assert validation_result["valid"], f"Schema validation failed: {validation_result.get('message')}"

    # Additional assertions based on scenario
    if scenario == "Successful responses: OK":
        assert response.json().get("code") == 200, "Expected code 200 in response"

